#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long row[61] = {0};
    row[0] = 1;
    for (int i = 0; i < n; ++i) {
        // Ensure the last element of the current row is 1
        row[i] = 1;
        // Compute interior values from right to left
        for (int j = i - 1; j > 0; --j) {
            row[j] = row[j] + row[j - 1];
        }
        // Print the row
        for (int j = 0; j <= i; ++j) {
            if (j) putchar(' ');
            printf("%lld", row[j]);
        }
        putchar('\n');
    }
    return 0;
}
